<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('student');
$db=Database::connection(); $student=(new Student($db))->profile(current_user_id());
$term=$db->query('SELECT * FROM academic_terms WHERE is_current=1 LIMIT 1')->fetch();
$filters=['q'=>trim((string)($_GET['q']??'')),'sort'=>(string)($_GET['sort']??'title'),'direction'=>(string)($_GET['direction']??'asc')];
$courses=(new Course($db))->browse($filters,$student,(int)($term['id']??0));
page_start('Browse courses','student/courses.php');
?>
<div class="content-width"><?php page_title('Browse courses',$term?'All active courses · Eligible for your department and semester':'All active courses · There is no active academic term.'); ?>
<div class="panel mb-4"><form class="row g-3 align-items-end" method="get"><div class="col-lg-6"><label class="form-label">Search courses</label><input class="form-control" name="q" value="<?= e($filters['q']) ?>" placeholder="Course code, title, or faculty"></div><div class="col-sm-5 col-lg-3"><label class="form-label">Sort by</label><select class="form-select" name="sort"><option value="title" <?= $filters['sort']==='title'?'selected':'' ?>>Course title</option><option value="credits" <?= $filters['sort']==='credits'?'selected':'' ?>>Credits</option><option value="seats" <?= $filters['sort']==='seats'?'selected':'' ?>>Available seats</option></select></div><div class="col-sm-4 col-lg-2"><label class="form-label">Order</label><select class="form-select" name="direction"><option value="asc" <?= $filters['direction']==='asc'?'selected':'' ?>>Ascending</option><option value="desc" <?= $filters['direction']==='desc'?'selected':'' ?>>Descending</option></select></div><div class="col-sm-3 col-lg-1 d-grid"><button class="btn btn-primary">Apply</button></div></form></div>
<div class="row g-3"><?php foreach($courses as $c): $seats=max(0,(int)$c['capacity']-(int)$c['enrolled']); ?>
<div class="col-md-6 col-xl-4"><article class="course-card"><div class="d-flex justify-content-between gap-2"><span class="course-code"><?= e($c['code']) ?></span><span class="badge text-bg-<?= $seats?'success':'secondary' ?>"><?= $seats ?> seats</span></div><h3><?= e($c['title']) ?></h3><p class="text-muted-custom small mb-2"><?= e($c['department_name'] ?: 'All departments') ?> · Semester <?= (int)$c['semester'] ?></p><div class="mb-3"><span class="badge text-bg-<?= $c['eligible']?'primary':'light' ?> <?= $c['eligible']?'':'text-secondary border' ?>"><?= $c['eligible']?'Eligible for you':'Different department or semester' ?></span></div><div class="small mb-2"><i class="bi bi-award me-2"></i><?= (int)$c['credits'] ?> credits <span class="mx-2">·</span><i class="bi bi-person me-1"></i><?= e($c['faculty_name']) ?></div><div class="small text-muted-custom mb-3"><i class="bi bi-calendar3 me-2"></i><?= e($c['schedule'] ?: 'Schedule not set') ?></div><div class="d-flex gap-2"><a class="btn btn-outline-primary btn-sm flex-grow-1" href="<?= e(url('student/course.php?id='.(int)$c['id'])) ?>">Details</a><?php if(!$c['eligible']): ?><button class="btn btn-light btn-sm text-secondary" disabled>Not eligible</button><?php elseif(!$term): ?><button class="btn btn-secondary btn-sm" disabled>Closed</button><?php elseif(!$seats): ?><button class="btn btn-secondary btn-sm" disabled>Full</button><?php else: ?><form method="post" action="<?= e(url('student/register.php')) ?>" data-confirm-submit="Send a registration request for <?= e($c['code']) ?>?"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><button class="btn btn-primary btn-sm">Register</button></form><?php endif; ?></div></article></div>
<?php endforeach; if(!$courses): ?><div class="col-12"><div class="panel empty-state"><i class="bi bi-search"></i><h3>No matching courses</h3><p>Try a different search term.</p></div></div><?php endif; ?></div>
</div>
<?php page_end(); ?>
